def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up_stem = 0
    down_stem = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            if len(component) != 4:
                continue
            rows = {}
            for x, y in component:
                rows.setdefault(x, []).append(y)
            bar_row = next((x for x, cols in rows.items() if len(cols) == 3), None)
            if bar_row is None:
                continue
            stem = next((p for p in component if p[0] != bar_row), None)
            if stem is None:
                continue
            if stem[0] < bar_row:
                up_stem += 1
            else:
                down_stem += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for i in range(min(up_stem, 4)):
        r, c = slots[i]
        out[r][c] = 3
    for i in range(min(down_stem, 4)):
        r, c = slots[i]
        out[r][c + 3] = 1
    return out

def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find zero cells connected to the edge by 4-way paths.
    exterior = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not exterior[nr][nc]):
                exterior[nr][nc] = True
                q.append((nr, nc))

    # Enclosed zero cells next to a contour become 3.
    enclosed_boundary = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not exterior[r][c]:
                near_one = False
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                            near_one = True
                            enclosed_boundary.add((nr, nc))
                if near_one:
                    out[r][c] = 3

    # Add a 2 halo outside the contour components that border an enclosure.
    marked = set(enclosed_boundary)
    q = deque(enclosed_boundary)
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                    and (nr, nc) not in marked):
                marked.add((nr, nc))
                q.append((nr, nc))

    for r, c in marked:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and exterior[nr][nc]):
                    out[nr][nc] = 2

    return out

