def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated strip gives the colors in top-to-bottom order.
    strip = None
    for r in range(h):
        end = r + 1
        while end < h and grid[end] == grid[r]:
            end += 1
        if end - r >= 2:
            cols = [c for c, v in enumerate(grid[r]) if v]
            if len(cols) > 1 and cols == list(range(cols[0], cols[-1] + 1)):
                seq = grid[r][cols[0]:cols[-1] + 1]
                if len(set(seq)) > 1:
                    strip = (r, end, cols[0], cols[-1] + 1, seq)
                    break

    if strip is None:
        return [row[:] for row in grid]

    sr, se, sc, ec, seq = strip
    strip_cells = {(r, c) for r in range(sr, se) for c in range(sc, ec)}

    # Find the component colored 1; diagonal contact is part of the shape.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in strip_cells or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in strip_cells and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            components.append((color, comp))

    anchor = [comp for color, comp in components if color == 1]
    if not anchor:
        return [row[:] for row in grid]
    comp = max(anchor, key=len)
    top, left = min(y for y, x in comp), min(x for y, x in comp)
    pattern = [(y - top, x - left) for y, x in comp]
    shape_h = max(dy for dy, dx in pattern) + 1
    index = seq.index(1)
    start_y = top - index * shape_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(seq):
        y0 = start_y + i * shape_h
        for dy, dx in pattern:
            y, x = y0 + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # Connect pairs of 1s lying on the same diagonal.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc) and dr != 0:
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                for k in range(1, abs(dr)):
                    r, c = r1 + sr * k, c1 + sc * k
                    if out[r][c] != 6:
                        out[r][c] = 1

    # A 6 on a connecting diagonal extends along its perpendicular diagonal.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                on_connector = any(
                    abs(r - r1) == abs(c - c1)
                    and abs(r - r2) == abs(c - c2)
                    and (r - r1) * (r2 - r) >= 0
                    and (c - c1) * (c2 - c) >= 0
                    and (r2 - r1) != 0
                    and abs(r2 - r1) == abs(c2 - c1)
                    for i, (r1, c1) in enumerate(ones)
                    for r2, c2 in ones[i + 1:]
                )
                if on_connector:
                    for step in range(-max(h, w), max(h, w) + 1):
                        rr, cc = r + step, c - step
                        if 0 <= rr < h and 0 <= cc < w:
                            out[rr][cc] = 6
    return out

def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the horizontal period of the repeated pattern.
    best_p, best_score = 2, -1
    for p in range(2, 11):
        matches = total = 0
        for r in range(3, h):
            for c in range(3, w - p):
                if grid[r][c] and grid[r][c + p]:
                    total += 1
                    matches += grid[r][c] == grid[r][c + p]
        score = matches / total if total else 0
        if score > best_score:
            best_p, best_score = p, score

    # The pattern advances one position both across and down.
    values = [Counter() for _ in range(best_p)]
    for r in range(3, h):
        for c in range(3, w):
            if grid[r][c] != 0:
                values[(r + c) % best_p][grid[r][c]] += 1

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 1 if c < 2 else 4
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                counts = values[(r + c) % best_p]
                out[r][c] = counts.most_common(1)[0][0] if counts else 0

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    centers = []

    # Find solid 3x3 monochromatic blocks.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[i][j] == color
                   for i in range(r, r + 3)
                   for j in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))

    out = [row[:] for row in grid]
    lines = {}
    for r, c, color in centers:
        for j in range(w):
            lines.setdefault((r, j), set()).add(color)
        for i in range(h):
            lines.setdefault((i, c), set()).add(color)

    for (i, j), colors in lines.items():
        out[i][j] = next(iter(colors)) if len(colors) == 1 else 0
    return out
